#include <bits/stdc++.h>
using namespace std;

const int MAXB = 1 << 19 | 5;
const int LAYERS = 20;

int n, k, p;
int lim, bits[MAXB], fvec[MAXB];
int bucketA[LAYERS][MAXB], bucketB[LAYERS][MAXB], bucketC[LAYERS][MAXB];
long long pp;
long long tempArr[LAYERS][MAXB];
long long fact[MAXB], invfact[MAXB];

long long binpow(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base % p;
        base = base * base % p;
        exp >>= 1;
    }
    return res;
}

void precompute_factorials() {
    fact[0] = 1;
    for (int i = 1; i <= lim; i++) fact[i] = fact[i - 1] * i % p;
    invfact[lim] = binpow(fact[lim], p - 2);
    for (int i = lim - 1; i >= 0; i--) invfact[i] = invfact[i + 1] * (i + 1) % p;
}

int get_power_bound(int x) {
    int v = 1;
    while (v < x) v <<= 1;
    return v;
}

void fwt_transform(int *vec, int len, bool invert = false) {
    long long *tmp = tempArr[0];
    for (int i = 0; i < len; i++) tmp[i] = vec[i];
    if (invert) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += (step << 1)) {
                for (int j = i; j < i + step; j++) {
                    tmp[j + step] -= tmp[j];
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += (step << 1)) {
                for (int j = i; j < i + step; j++) {
                    tmp[j + step] += tmp[j];
                }
            }
        }
    }
    for (int i = 0; i < len; i++) {
        vec[i] = tmp[i] % p;
        if (vec[i] < 0) vec[i] += p;
    }
}

inline void safe_add(long long &x) {
    if (x >= pp) x -= pp;
}

void combine(int *result, bool self) {
    static int store[LAYERS][MAXB];
    if (self) {
        for (int i = 0; i < LAYERS; i++) memset(tempArr[i], 0, sizeof(long long) * (lim + 1));
        for (int a = 0; a < LAYERS; a++)
            for (int b = 0; a + b < LAYERS; b++)
                for (int i = 0; i <= lim; i++)
                    safe_add(tempArr[a + b][i] += 1LL * bucketB[a][i] * bucketB[b][i]);
        for (int a = 0; a < LAYERS; a++)
            for (int i = 0; i <= lim; i++)
                store[a][i] = tempArr[a][i] % p;
        for (int a = 0; a < LAYERS; a++) fwt_transform(store[a], lim + 1, true);
        for (int a = 0; a < LAYERS; a++) memset(bucketB[a], 0, sizeof(int) * (lim + 1));
        for (int i = 0; i <= lim; i++) bucketB[bits[i]][i] = store[bits[i]][i];
        for (int a = 0; a < LAYERS; a++) fwt_transform(bucketB[a], lim + 1);
    } else {
        for (int i = 0; i < LAYERS; i++) {
            memset(bucketA[i], 0, sizeof(int) * (lim + 1));
            memset(tempArr[i], 0, sizeof(long long) * (lim + 1));
        }
        for (int i = 0; i <= lim; i++) bucketA[bits[i]][i] = fvec[i];
        for (int a = 0; a < LAYERS; a++) fwt_transform(bucketA[a], lim + 1);
        for (int a = 0; a < LAYERS; a++)
            for (int b = 0; a + b < LAYERS; b++)
                for (int i = 0; i <= lim; i++)
                    safe_add(tempArr[a + b][i] += 1LL * bucketA[a][i] * bucketB[b][i]);
        for (int a = 0; a < LAYERS; a++)
            for (int i = 0; i <= lim; i++)
                bucketC[a][i] = tempArr[a][i] % p;
        for (int a = 0; a < LAYERS; a++) fwt_transform(bucketC[a], lim + 1, true);
        for (int i = 0; i <= lim; i++) fvec[i] = bucketC[bits[i]][i];
    }
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    pp = 1LL * p * p;
    if (n & 1) {
        printf("%lld", binpow(k, n));
        return 0;
    }
    fvec[0] = 1;
    lim = get_power_bound(n + 1) - 1;
    precompute_factorials();
    for (int i = 0; i <= lim; i++) bits[i] = __builtin_popcount(i);
    for (int i = 0; i <= lim; i++) bucketB[bits[i]][i] = invfact[i];
    for (int i = 0; i < LAYERS; i++) fwt_transform(bucketB[i], lim + 1);
    int orig = k;
    while (k) {
        cerr << k << endl;
        if (k & 1) combine(bucketC, false);
        k >>= 1;
        if (k) combine(bucketC, true);
    }
    printf("%lld", (binpow(orig, n) - fact[n] * fvec[n] % p + p) % p);
    return 0;
}
